('it', $t$Sources : <a href="https://clerk.house.gov/Votes">greffe de la Chambre</a> (officiel) ; Sénat via <a href="https://voteview.com/">Voteview</a> (UCLA, Université de Géorgie) d'après les <a href="https://www.senate.gov/legislative/votes_new.htm">enregistrements du Sénat</a>.$t$, $t$Fonti: <a href="https://clerk.house.gov/Votes">Clerk of the House</a> (ufficiale); Senato tramite <a href="https://voteview.com/">Voteview</a> (UCLA, University of Georgia) dai <a href="https://www.senate.gov/legislative/votes_new.htm">resoconti del Senato</a>.$t$),
('it', $t$Sources : <a href="https://commonsvotes-api.parliament.uk/">Parlement britannique, API Commons et Lords Votes</a> (<a href="https://www.parliament.uk/site-information/copyright-parliament/open-parliament-licence/">Open Parliament Licence</a>).$t$, $t$Fonte: <a href="https://commonsvotes-api.parliament.uk/">Parlamento del Regno Unito, API dei voti dei Comuni e dei Lord</a> (<a href="https://www.parliament.uk/site-information/copyright-parliament/open-parliament-licence/">Open Parliament Licence</a>).$t$),
('it', $t$Sources : <a href="https://data.assemblee-nationale.fr/">data.assemblee-nationale.fr</a>, <a href="https://data.senat.fr/">data.senat.fr</a>, pétitions via <a href="https://www.data.gouv.fr/">data.gouv.fr</a>, Parlement européen via <a href="https://howtheyvote.eu/">HowTheyVote.eu</a> (<a href="https://opendatacommons.org/licenses/odbl/1-0/">ODbL</a>).$t$, $t$Fonti: <a href="https://data.assemblee-nationale.fr/">data.assemblee-nationale.fr</a>, <a href="https://data.senat.fr/">data.senat.fr</a>, petizioni tramite <a href="https://www.data.gouv.fr/">data.gouv.fr</a>, Parlamento europeo tramite <a href="https://howtheyvote.eu/">HowTheyVote.eu</a> (<a href="https://opendatacommons.org/licenses/odbl/1-0/">ODbL</a>).$t$),
('it', $t$Sources : <a href="https://dati.camera.it/">dati.camera.it</a>, open data de la Chambre des députés (<a href="https://creativecommons.org/licenses/by-sa/4.0/deed.fr">CC BY-SA 4.0</a>) ; <a href="https://dati.senato.it/">dati.senato.it</a>, open data du Sénat.$t$, $t$Fonti: <a href="https://dati.camera.it/">dati.camera.it</a>, dati aperti della Camera dei deputati (<a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a>); <a href="https://dati.senato.it/">dati.senato.it</a>, dati aperti del Senato.$t$),
